          if (!tooltipLayer || supportsAnchorPositioning()) return;

          const triggerRect = trigger.getBoundingClientRect();
          const tooltipRect = tooltipLayer.getBoundingClientRect();
          const gap = 10;
          const viewportPadding = 12;

          let left = triggerRect.left + triggerRect.width / 2 - tooltipRect.width / 2;
          left = Math.max(
              viewportPadding,
              Math.min(left, innerWidth - tooltipRect.width - viewportPadding)
          );

          let top = triggerRect.top - tooltipRect.height - gap;
          let placement = "above";

          if (top < viewportPadding) {
              top = triggerRect.bottom + gap;
              placement = "below";
          }

          tooltipLayer.dataset.placement = placement;
          tooltipLayer.style.setProperty("inset-inline-start", `${left}px`);
          tooltipLayer.style.setProperty("inset-block-start", `${top}px`);
